questionvariables.text:
thetalist : [30, 45, 60];
theta : rand(thetalist);
RR : rand_with_step(2, 6, 1);            /* circumradius, integer 2..6 */
bc_rad : if theta = 30 then 1 elseif theta = 45 then 2 else 3;
bc_coef : RR;
BC : bc_coef * sqrt(bc_rad);             /* chord, exact integer or surd */
ta1 : theta;                             /* model answer: angle in degrees */
sinexact : BC/(2*RR);                    /* = sin(theta): 1/2, sqrt(2)/2 or sqrt(3)/2 */
sinval : float(sinexact);                /* decimal value of sin(theta), for a diagnostic */
twotheta: theta * 2; /* Central angle */
supp : 180 - theta;                      /* obtuse supplement (same sine) */
